    Bug 2000462 - Fix cache check to work with disabled RCWN. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D272873

diff --git a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
index 09078698786..1266e3aa51c 100644
--- a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
+++ b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
@@ -92,13 +92,17 @@ export const NotificationUpdater = {
         .asyncOpenURI(
           Services.io.newURI(url),
           "",
-          Ci.nsICacheStorage.READ_ONLY,
+          Ci.nsICacheStorage.OPEN_READONLY,
           {
             onCacheEntryCheck() {
               return Ci.nsICacheEntryOpenCallback.ENTRY_WANTED;
             },
-            onCacheEntryAvailable({ expirationTime }) {
-              resolve(expirationTime);
+            onCacheEntryAvailable(entry, _new, result) {
+              if (result !== Cr.NS_OK) {
+                resolve(0);
+                return;
+              }
+              resolve(entry?.expirationTime);
             },
           }
         );
